transforms.code:
security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureMaintenance']['enabled']: 
		canCreate = True
		canEdit = True if len(value['data']) > 0 else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

config.script:
if self.view.custom.part.userAction.canUpdate:
	partId = self.props.data[event.row]['partId']

	if event.column in ('enabled', 'sortOrder'):
		retVal, msg = system.kanoa.cmms.updatepartField(partId, event.column, event.value, self.view.custom.security.userId)			
		if msg: system.perspective.sendMessage('showFailerToast', {'message': 'Failed to update the work order status. %s'%msg})
		else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Work Order Status has been updated'})		
	else:
		system.perspective.sendMessage('showFailerToast', 'Column is not enabled for editing')
else:
	system.perspective.sendMessage('showFailerToast', 'No permissions to update')

self.view.refreshBinding("custom.part.data")
self.props.selection.selectedRow = None	
self.props.selection.selectedCol = None	

return

customMethods.script:

partInfo = self.view.custom.part.selectedData[0]
if partInfo.get('partId'):
	retVal, msg = system.kanoa.inventory.deletePartInventoryPolicy(partInfo['partInventoryPolicyId'], self.view.custom.security.userId)
	if retVal:
		system.perspective.sendMessage('showSuccessfulToast', {'message': 'Record has been deleted'})
	else:
		if 'The DELETE statement conflicted with the REFERENCE constraint' in str(msg) or 'The DELETE statement conflicted with the SAME TABLE REFERENCE constraint' in str(msg):
			msg = 'This record has been used and cannot be deleted. Please disable it.'
		system.perspective.sendMessage('showFailerToast', {'message': msg})

	self.view.refreshBinding("custom.part.data")

return
